from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode


def apply_rewrite_rules(rules, urls):
    def replace_host(parts, new_host):
        # Preserve user information, if present.
        userinfo = ""
        if "@" in parts.netloc:
            userinfo = parts.netloc.rsplit("@", 1)[0] + "@"

        # Preserve the original port.
        port = ""
        if parts.port is not None:
            port = f":{parts.port}"

        # Bracket IPv6 hostnames when rebuilding the URL.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        return parts._replace(
            netloc=f"{userinfo}{new_host}{port}"
        )

    results = []

    for url in urls:
        parts = urlsplit(url)
        rewritten_url = url
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            is_match = False

            if match_type == "path_prefix":
                is_match = parts.path.startswith(match_value)

            elif match_type == "host":
                host = (parts.hostname or "").lower()
                expected = match_value.lower()

                if expected.startswith("*."):
                    base_domain = expected[2:]
                    is_match = (
                        host != base_domain
                        and host.endswith("." + base_domain)
                    )
                else:
                    is_match = host == expected

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parts.query,
                    keep_blank_values=True
                )
                is_match = any(
                    name == match_value
                    for name, _ in query_params
                )

            if not is_match:
                continue

            matched = True

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                removal = rule["action_value"]
                path = parts.path

                if path.startswith(removal):
                    new_path = path[len(removal):] or "/"
                    rewritten_url = urlunsplit(
                        parts._replace(path=new_path)
                    )

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    replace_host(parts, rule["action_value"])
                )

            elif action == "add_query_param":
                query_params = parse_qsl(
                    parts.query,
                    keep_blank_values=True
                )
                new_params = parse_qsl(
                    rule["action_value"],
                    keep_blank_values=True
                )
                query_params.extend(new_params)

                rewritten_url = urlunsplit(
                    parts._replace(
                        query=urlencode(query_params, doseq=True)
                    )
                )

            else:
                raise ValueError(f"Unsupported action: {action}")

            # Only the first matching rule is used.
            break

        results.append(rewritten_url if matched else url)

    return results
